#!/bin/bash
# P5f cluster task: one functional gate-level simulation (zero delay, cell models generated by Yosys 0.33 from
# the NanGate45 liberty, locally). Called by an sbatch array; line SLURM_ARRAY_TASK_ID (1-based) of the task
# list "<kind> <run>" selects kind = sim (unmodified rtl/v2/tb_lfu_cache.sv via tools/p5f_wrap.py) or
# lockstep (synthesis/p5f/tb_gls_lockstep.sv, 200,000 cycles). vvp is capped at 2 h (timeout 7200; 124 = hit).
# Times and peak memory come from tools/timev.py (GNU time is missing on compute nodes).
#   sbatch ... gls_task.sh <tasklist>
set -uo pipefail
G=/scratch/rahulkmr/Adarsh/gls
E=/home/rahulkmr/.conda/envs/rtl_sim/bin
read -r kind run < <(sed -n "${SLURM_ARRAY_TASK_ID}p" "$1")
d=${run#d}; d=${d%%_*}; m=${run#*_m}; m=${m%%_*}
w=$G/work/$kind/$run; o=$G/results/$kind/$run.txt; mkdir -p "$w" "$G/results/$kind"
cd "$w" || exit 1
{
echo "# $kind $run: functional gate-level simulation, zero delay, cell models generated by Yosys from the liberty file"
echo "job ${SLURM_ARRAY_JOB_ID:-?}_${SLURM_ARRAY_TASK_ID:-?} host $(hostname) cpus ${SLURM_CPUS_PER_TASK:-?} mem ${SLURM_MEM_PER_NODE:-?} MB"
echo "iverilog: $($E/iverilog -V 2>&1 | head -n 1)"
echo "netlist sha256: $(sha256sum "$G/netlists/$run/netlist.v" | cut -d' ' -f1)"
"$E/python3" -I "$G/tools/p5f_wrap.py" "$G/netlists/$run/netlist.v" "$d" "$m" "$w" || { echo "wrap failed"; exit 1; }
if [ "$kind" = sim ]; then
    src=("$G/models/nangate45_cells_yosys.v" "$w/netlist_gl.v" "$w/wrapper.v" "$G/rtl/tb_lfu_cache.sv")
    par=(-Ptb_lfu_cache.COUNTER_MODE=$m -Ptb_lfu_cache.CACHE_DEPTH=$d)
else
    src=("$G/models/nangate45_cells_yosys.v" "$w/netlist_gl.v" "$G/rtl/lfu_cache_controller.v" "$G/tb/tb_gls_lockstep.sv")
    par=(-Ptb_gls_lockstep.COUNTER_MODE=$m -Ptb_gls_lockstep.CACHE_DEPTH=$d)
fi
echo "== compile"
"$E/python3" -I "$G/tools/timev.py" "$E/iverilog" -g2012 "${par[@]}" -o "$w/$kind.vvp" "${src[@]}" > iverilog.txt 2> compile_time.txt
rc=$?
grep -v timescale iverilog.txt | sort | uniq -c | head -n 20
grep -E "Elapsed|Maximum resident|Exit status" compile_time.txt
if [ $rc = 0 ]; then
    echo "== run (2 h limit)"
    "$E/python3" -I "$G/tools/timev.py" timeout 7200 "$E/vvp" -n "$kind.vvp" > vvp.txt 2> run_time.txt
    echo "vvp exit=$? (124 = 2 h limit hit)"
    grep -E "Elapsed|Maximum resident|Exit status" run_time.txt
    grep -v '^\$finish\|finish called\|^VCD' vvp.txt   # at most 20 progress + 10 mismatch + 10 X lines + 2
fi
} > "$o" 2>&1
